def count_by_initial(words):
    out = {}
    for word in words:
        if word:
            key = word[0].lower()
            out[key] = out.get(key, 0) + 1
    return out

def unique_by_initial(words):
    groups = {}
    for word in words:
        if word:
            key = word[0].lower()
            groups.setdefault(key, set()).add(word.lower())
    return {key: len(values) for key, values in groups.items()}

def parse_pairs(lines):
    out = {}
    for line in lines:
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            if key:
                out[key] = value.strip()
    return out

def parse_typed_pairs(lines):
    out = {}
    for line in lines:
        if '=' not in line:
            continue
        key, value = line.split('=', 1)
        key, value = key.strip(), value.strip()
        if not key:
            continue
        low = value.lower()
        if low in ('true', 'false'):
            out[key] = low == 'true'
        elif value.lstrip('-').isdigit():
            out[key] = int(value)
        else:
            out[key] = value
    return out

def rotate_left(items, k):
    if not items:
        return []
    n = k % len(items)
    return items[n:] + items[:n]

def rotate_right(items, k):
    if not items:
        return []
    n = k % len(items)
    return items[-n:] + items[:-n] if n else list(items)

def merge_intervals(intervals):
    ordered = sorted(intervals)
    out = []
    for start, end in ordered:
        if not out or start > out[-1][1] + 1:
            out.append([start, end])
        else:
            out[-1][1] = max(out[-1][1], end)
    return out

def merge_with_gap(intervals, max_gap):
    out = []
    for start, end in sorted(intervals):
        if not out or start - out[-1][1] - 1 > max_gap:
            out.append([start, end])
        else:
            out[-1][1] = max(out[-1][1], end)
    return out

def balanced_brackets(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def bracket_depth(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    best = 0
    for ch in text:
        if ch in '([{':
            stack.append(ch)
            best = max(best, len(stack))
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return -1
    return best if not stack else -1

def shortest_hops(edges, start, end):
    if start == end:
        return 0
    queue = [[start, 0]]
    seen = {start}
    for node, dist in queue:
        for left, right in edges:
            if left == node and right not in seen:
                if right == end:
                    return dist + 1
                seen.add(right)
                queue.append([right, dist + 1])
    return -1

def shortest_undirected_hops(edges, start, end):
    if start == end:
        return 0
    queue = [[start, 0]]
    seen = {start}
    for node, dist in queue:
        for left, right in edges:
            nxt = right if left == node else left if right == node else None
            if nxt is not None and nxt not in seen:
                if nxt == end:
                    return dist + 1
                seen.add(nxt)
                queue.append([nxt, dist + 1])
    return -1

def longest_nondecreasing(values):
    if not values:
        return 0
    best = [1] * len(values)
    for i in range(len(values)):
        for j in range(i):
            if values[j] <= values[i]:
                best[i] = max(best[i], best[j] + 1)
    return max(best)

def valid_slug(text):
    if not text or text[0] == '-' or text[-1] == '-':
        return False
    previous = ''
    for ch in text:
        if not (ch.isdigit() or ('a' <= ch <= 'z') or ch == '-'):
            return False
        if ch == '-' and previous == '-':
            return False
        previous = ch
    return True

def split_ascii_slug(text):
    if not text or text[0] == '-' or text[-1] == '-':
        return []
    previous = ''
    for ch in text:
        if not (('0' <= ch <= '9') or ('a' <= ch <= 'z') or ch == '-'):
            return []
        if ch == '-' and previous == '-':
            return []
        previous = ch
    return text.split('-')

def run_length_encode(text):
    out = []
    for ch in text:
        if out and out[-1][0] == ch:
            out[-1][1] += 1
        else:
            out.append([ch, 1])
    return out

def window_sums(values, k):
    if k <= 0 or k > len(values):
        return []
    return [sum(values[i:i+k]) for i in range(len(values)-k+1)]

def window_averages(values, k):
    if k <= 0 or k > len(values):
        return []
    return [sum(values[i:i+k]) / k for i in range(len(values)-k+1)]

def apply_transactions(balance, transactions):
    for amount in transactions:
        if balance + amount >= 0:
            balance += amount
    return balance

def transaction_summary(balance, transactions):
    skipped = 0
    for amount in transactions:
        if balance + amount < 0:
            skipped += 1
        else:
            balance += amount
    return [balance, skipped]

def ready_steps(dependencies, completed):
    done = set(completed)
    return sorted(step for step, needs in dependencies.items() if step not in done and all(item in done for item in needs))

def blocked_steps(dependencies, completed):
    done = set(completed)
    return sorted(step for step, needs in dependencies.items() if step not in done and any(item not in done for item in needs))
